+        Ok(Some(match fragment {
+            Fragment::Line { data } => {
+                Bound::new(slf.py(), PyLineFragment::new(data))?.to_object(slf.py())
+            }
+            Fragment::Literal { data, mode } => {
+                Bound::new(slf.py(), PyLiteralFragment::try_new(data, mode.into())?)?
+                    .to_object(slf.py())
+            }
+        }))
+    }
