+
+    // Generic setting
+    println!("cargo:rerun-if-changed=build.rs");
+
+    // feature `error-in-core` landed in rust 1.81.0
+    if matches!(version_meta.channel, Channel::Nightly) || version.minor >= 81 {
+        println!("cargo:rustc-cfg=ERROR_IN_CORE");
+    }
+}
