    "end": 26
  },
  "language": "Cpp",
  "metaVariables": {
    "single": {
      "COMMENT": {
        "text": "//  TODO test stuff.....",
        "range": {
          "byteOffset": {
            "start": 2,
            "end": 26
          },
          "start": {
            "line": 0,
            "column": 2
          },
          "end": {
            "line": 0,
            "column": 26
          }
        }
      }
    },
    "multi": {},
    "transformed": {
      "NEW_COMMENT": "//  TODO: test stuff....."
    }
  },
  "ruleId": "comment",
  "severity": "hint",
  "note": null,
  "message": ""
},
{
  "text": "//  TODO teste Übergänge",
  "range": {
    "byteOffset": {
      "start": 29,
      "end": 55
    },
    "start": {
      "line": 1,
      "column": 2
    },
    "end": {
      "line": 1,
      "column": 28
    }
  },
  "file": "comment.cpp",
  "lines": "  //  TODO teste Übergänge",
  "charCount": {
    "leading": 2,
    "trailing": 0
  },
  "replacement": "//  TODO: teste Übergänge",
  "replacementOffsets": {
    "start": 29,
    "end": 55
  },
  "language": "Cpp",
  "metaVariables": {
    "single": {
      "COMMENT": {
        "text": "//  TODO teste Übergänge",
        "range": {
          "byteOffset": {
            "start": 29,
            "end": 55
          },
          "start": {
            "line": 1,
            "column": 2
          },
          "end": {
            "line": 1,
            "column": 28
          }
        }
      }
    },
    "multi": {},
    "transformed": {
      "NEW_COMMENT": "//  TODO: teste Übergänge"
    }
  },
  "ruleId": "comment",
  "severity": "hint",
  "note": null,
  "message": ""
}
]
```

Although both comment matches have the end column 26, ast-grep scan reports end column 28 for the comment with special characters.

### 🙂 Expected behavior

Ast-grep scan should report the actual end column.

