+  // Thread 2: Wait for the child to exit in another thread
+  let mut ffmpeg_child = command.spawn()?;
+  thread::spawn(move || {
+    ffmpeg_child.wait().unwrap();
+    sender.send("ffmpeg").ok();
+  });
