+                    return helper_err!(
+                        "qsv_loadjson",
+                        "Failed to convert JSON to Luau value: {e}"
+                    );
+                },
+            };
+
+            luau.globals().raw_set(table_name.clone(), luau_value)?;
+
+            info!(
+                "{} successfully loaded JSON into table '{}'.",
+                filepath, table_name
